import sys

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    answers = [(x[0], int(x[1:])) for x in input[2:]]

    truth_count = [0] * (n + 1)
    for i, (sign, ai) in enumerate(answers):
        if sign == '+':
            truth_count[ai] += 1

    for i, (sign, ai) in enumerate(answers):
        suspect = i + 1
        if sign == '+':
            if truth_count[ai] == m:
                print("Truth")
            elif truth_count[ai] == m - 1:
                print("Not defined")
            else:
                print("Lie")
        else:
            if truth_count[ai] == m:
                print("Lie")
            elif truth_count[ai] == m - 1:
                if ai != suspect:
                    print("Not defined")
                else:
                    print("Truth")
            else:
                print("Not defined")

if __name__ == "__main__":
    main()
